import pytest
from candidate import how_many_times

def test_how_many_times_empty_string_empty_substring():
    assert how_many_times('', '') == 0

def test_how_many_times_empty_string_nonempty_substring():
    assert how_many_times('', 'a') == 0

def test_how_many_times_nonempty_string_empty_substring():
    assert how_many_times('a', '') == 0

def test_how_many_times_nonempty_string_nonempty_substring():
    assert how_many_times('aaa', 'a') == 3

def test_how_many_times_exact_match():
    assert how_many_times('aaaa', 'aa') == 2

def test_how_many_times_overlapping_substring():
    assert how_many_times('aaabaa', 'aa') == 3
